<?php $e = static fn (mixed $v): string => App\Core\View::e($v); $base = App\Core\Config::url('/prestacao/campeonatos/' . $championshipId); ?><section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Prestação de contas · Partida #<?= (int) $match['id'] ?></p><h1><?= $e($match['home_team_name']) ?> x <?= $e($match['away_team_name']) ?></h1><p class="muted"><?= $e($match['match_date']) ?> · <?= $e($match['venue_name'] ?: 'Local não informado') ?> · Documentação: <?= $e($match['document_status']) ?></p></div><a class="button secondary" href="<?= $e($base) ?>">Voltar</a></div><?php if (!empty($match['events'])): ?><article class="panel"><h2>Registros esportivos</h2><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Equipe</th><th>Atleta</th><th>Minuto</th><th>Situação</th></tr></thead><tbody><?php foreach ($match['events'] as $event): ?><tr><td><?= $e($event['event_type']) ?></td><td><?= $e($event['team_name'] ?? '-') ?></td><td><?= $e($event['sporting_name'] ?: ($event['athlete_name'] ?? '-')) ?></td><td><?= $e($event['minute'] ?? '-') ?></td><td><?= (int) $event['valid'] === 1 ? 'Válido' : 'Anulado' ?></td></tr><?php endforeach; ?></tbody></table></div></article><?php endif; ?><article class="panel"><h2>Versões da súmula</h2><?php foreach ($match['versions'] as $version): ?><div class="list-row"><span>Versão <?= (int) $version['version_number'] ?> · <?= $e($version['verification_code']) ?></span><span><?= !empty($version['signed_storage_path']) ? 'Assinada' : 'Sem assinatura' ?></span></div><?php endforeach; ?><form method="post" enctype="multipart/form-data" action="<?= $e($base . '/partidas/' . $match['id'] . '/sumula-assinada') ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Anexar cópia assinada em PDF<input type="file" name="signed_report" accept="application/pdf" required></label><button type="submit">Vincular documento</button></form></article><?php if (!empty($match['evidencias'])): ?><article class="panel"><h2>Evidências aprovadas</h2><div class="table-wrap"><table><thead><tr><th>Título</th><th>Arquivo</th><th>Data</th></tr></thead><tbody><?php foreach ($match['evidencias'] as $evidence): ?><tr><td><?= $e($evidence['title']) ?></td><td><?= $e($evidence['original_name']) ?></td><td><?= $e($evidence['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></article><?php endif; ?></section>
